!************************************************************************
! This is a Fortran implementation of the ML-GPR PES for the ArH2+ system.
! This code was specifically built to facilitate the interfacing with
! (dynamics) codes written in Fortran, such as ABC.
! The inputs are the training data file, the optimised values of the
! hyperparameters, and the K^-1 * E vector (output from python).
! The potential units are Hartree and are measured wrt the ArHp + H asymp.
! The internuclear distances are measured in Angstrom.
! r0: the HH' internuclear distance.
! r1: the ArH internuclear distance.
! r2: the ArH' internuclear distance.
! Written by M. Konings. at KU Leuven
!*************************************************************************

module arh2p_pes 
      use, intrinsic :: iso_c_binding
      real*8,parameter :: pi=4.0*atan(1.d0)
      real*8,parameter :: twopi=2.d0*pi

      real*8,parameter :: d2r=pi/180.d0

      real*8,parameter :: bohr_to_angst=0.5291772d0

      !-------------------------------------------------
      integer, parameter :: ntrain = 5852     

      real*8, dimension(ntrain) :: F
      real*8, dimension(ntrain,3) :: r
      !-------------------------------------------------

      public :: init_pes, pes_gpr

contains

     !==============================================
      subroutine init_pes() bind(C, name="init_pes")
     !==============================================
      implicit none
      !matrix elements of (K - sig * I)^-1 * E
      call fetch_matelem()

      ! Read file with exponential training geometries.
      ! Data in file is presented in following format: exp(-r0),exp(-r1),exp(-r2).
      ! This file includes the permuted r1,r2 pairs.

      call fetch_training_geom()

      !init_pes = 1
      end subroutine 
     !==============================================


     !==============================================
      real(c_double) function pes_gpr(rdist) bind(C, name="pes_gpr")
     !==============================================

      use iso_c_binding, only: c_double
      implicit none
      real(c_double), dimension(3), intent(in) :: rdist  ! Input array

      integer, parameter :: p = 1                           ! This the value of p in nu = p + 1/2 !
      double precision, parameter :: n = 5.89D-05           ! This is the optimised value of the parameter n in the whitenoise kernel.
      double precision, parameter :: l0 = 16.9              ! These are the optimised values of the length scales in the Matern kernel,
      double precision, parameter :: l1 = 15.9              ! l0 corresp. to r0, l1 corresp. to r1, l2 corresp. to r2,
      double precision, parameter :: l2 = 15.9              ! l0 corresp. to HH internuclear distance, l1 and l2 to ArH and ArH' distances.
      double precision, parameter :: sigma = 308            ! This is the optimised value of the parameter sigma in the dot product kernel.
      double precision :: kk(ntrain)                       ! This is the other vector.
      double precision :: w,d,m
      double precision :: pred
      real*8, dimension(3) :: geom 
      integer :: i,j


      ! r0: the HH' internuclear distance.
      ! r1: the ArH internuclear distance.
      ! r2: the ArH' internuclear distance.


     !H-O1 distance
!      TT(4) = Q(4)-Q(1)
!      TT(5) = Q(5)-Q(2)
!      TT(6) = Q(6)-Q(3)
!      RR(2) = SQRT(TT(4)*TT(4)+TT(5)*TT(5)+TT(6)*TT(6))
     !------------------------------------------------------
     !H-O2 distance
!      TT(7) = Q(7)-Q(1)
!      TT(8) = Q(8)-Q(2)
!      TT(9) = Q(9)-Q(3)
!      RR(3) = SQRT(TT(7)*TT(7)+TT(8)*TT(8)+TT(9)*TT(9))
     !------------------------------------------------------
     !O1-O2 distance
!      TT(1) = Q(7)-Q(4)
!      TT(2) = Q(8)-Q(5)
!      TT(3) = Q(9)-Q(6)
!      RR(1) = SQRT(TT(1)*TT(1)+TT(2)*TT(2)+TT(3)*TT(3))


!    the original derivatives from ho2excpot function:
!    GRAD(1) = dV/dROO
!    GRAD(2) = dV/dRO1H
!    GRAD(3) = dV/dRO2H
!---------------------------------------------------------------------------
!    transformation the derivatives  from (ROO,RO1H,theta) --> (q(i), i=1-9):
!
!    dV/dq(i)=(dV/dROO)�~W(dROO/dq(i)) + (dV/dRO1H)�~W(dRO1H/dq(i)) + (dV/dRO2H)�~W(dRO2H/dq(i))  
!
!    pdot = dp(i)/dt = -dH/q(i) = -dV/dq(i) 
!--------------------------------------------------------------------------
!      do i=1,3
!       dROOdq(i)   =  0.0d0
!       dROOdq(i+3) = -TT(i)/RR(1)
!       dROOdq(i+6) = -dROOdq(i+3)
!      enddo

!      do i=1,3
!       dRO1Hdq(i)   = -TT(i+3)/RR(2)
!       dRO1Hdq(i+3) = -dRO1Hdq(i)
!       dRO1Hdq(i+6) =  0.0d0
!      enddo

!      do i=1,3
!       dRO2Hdq(i)   = -TT(i+6)/RR(3)
!       dRO2Hdq(i+3) =  0.0d0
!       dRO2Hdq(i+6) = -dRO2Hdq(i)
!      enddo

!   pdot = dp(i)/dt = -dH/q(i) = -dV/dq(i)
!
!   dV/dq(i)=(dV/dROO)�~W(dROO/dq(i)) + (dV/dRO1H)�~W(dRO1H/dq(i)) + (dV/dRO2H)�~W(dRO2H/dq(i))  
!----------------------------------------------------------------------------------------
!   force-vector component: 
!-------------------------
!      do i=1,9
!      PDOT(i) = GRAD(1)*dROOdq(i)+GRAD(2)*dRO1Hdq(i)+GRAD(3)*dRO2Hdq(i)
!      enddo




      ! Give geometries for which enery needs to be calculated,
      ! build the kk vector,
      ! evaluate the energy prediction.
      kk = 0
      geom(1) = dexp(-rdist(1))
      geom(2) = dexp(-rdist(2))
      geom(3) = dexp(-rdist(3))
      do j=1,ntrain
         call whitenoise(n,r(j,:),geom(:),w)
         call dotproduct(sigma,r(j,:),geom(:),d)
         call Matern(p,l0,l1,l2,r(j,:),geom(:),m)

         kk(j) = d * m + w
      enddo
      pred = dot_product(kk,F) - (-1.9985d0)

      PES_GPR = pred / 27.2114 !from eV to Hartree

      return
      end
     !==============================================


     !==============================================
      subroutine kronecker_delta(a,b,result)
     !==============================================
      implicit none
      double precision :: a,b
      integer :: result

      if (a == b) then
         result = 1
      else
         result = 0
      endif

      return
      end subroutine
     !==============================================

     !==============================================
      subroutine whitenoise(a,x1,x2,b)
     !==============================================
      !This is the function corresponding to the white noise kernel.
      implicit none
      double precision :: a,b
      integer :: b1,b2,b3
      double precision :: x1(3),x2(3)

      call kronecker_delta(x1(1),x2(1),b1)
      call kronecker_delta(x1(2),x2(2),b2)
      call kronecker_delta(x1(3),x2(3),b3)

      b = a * b1
      b = b * b2
      b = b * b3

      return
      end subroutine
     !==============================================

     !==============================================
      subroutine dotproduct(a,x1,x2,b)
      !this is the function corresponding to the dot product kernel.
      implicit none
      double precision :: a,b
      double precision :: x1(3),x2(3)

      b = (a*a) + dot_product(x1,x2)

      end subroutine
     !==============================================

     !==============================================
      subroutine Matern(p,lx,ly,lz,x1,x2,result)
     !==============================================
      implicit none
      integer :: p
      double precision:: distx,disty,distz
      double precision :: lx,ly,lz, result, dist
      double precision :: x1(3),x2(3)
      double precision :: dx, dy, dz

      distx = abs(x1(1)-x2(1))
      disty = abs(x1(2)-x2(2))
      distz = abs(x1(3)-x2(3))

      dx = distx/lx
      dy = disty/ly
      dz = distz/lz
      dist = dsqrt(dx*dx + dy*dy + dz*dz)

      result = (1 + dsqrt(2.d0 * (p + 0.5)) * dist)
      result = result * dexp(-dsqrt(2.d0 * (p + 0.5)) * dist)

      return
      end subroutine
